const fs=require('node:fs');
const V=m=>{console.error('LU_API_BOUNDARY_VIOLATION: '+m);process.exit(1)};
const H=m=>{console.error('LU_API_BOUNDARY_HARNESS_ERROR: '+m);process.exit(2)};
try{
 const root='packages/mps-lu/src/index.ts';
 if(!fs.existsSync(root))H('load-bearing LU package root missing');
 const src=fs.readFileSync(root,'utf8');
 if(!src.includes('runCanonicalLuProductAssessment'))H('LU package-root positive control missing');
 const required=['packages/mps-lu/api-boundary.snapshot.json','scripts/dev-helpers/lib/luApiBoundary.mjs','tests/unit/luApiBoundaryStep4.test.ts'];
 const present=required.filter(p=>fs.existsSync(p));
 if(present.length===0)V('LU API boundary snapshot/import rule absent');
 if(present.length!==required.length)H('partial LU API boundary presence: '+present.join(', '));
 console.log('LU_API_BOUNDARY_OK: boundary artifacts present');
}catch(e){H('unexpected: '+(e&&e.stack?e.stack:e))}

